def hook(kwargs, charge='1.25'):
    kwargs['response_hook']({'x-ms-request-charge': charge}, {})

class Results:
    def __init__(self): self.n = 0
    def by_page(self):
        for docs, charge in [([DOC], '2.1'), ([dict(DOC, id='2')], '3.2')]:
            self.n += 1; self.charge = charge; yield iter(docs)
    def get_response_headers(self): return {'x-ms-request-charge': self.charge}
class Sync:
    def create_item(self, body, **kw): hook(kw); return dict(body, _etag='v1')
    def read_item(self, **kw): hook(kw); return DOC
    def replace_item(self, **kw): hook(kw); return dict(kw['body'], _etag='v2')
    def delete_item(self, **kw): hook(kw)
    def query_items(self, **kw):
        assert kw['parameters'] == [{'name':'@category','value':'c'}]
        assert kw['max_item_count'] == 1
        return Results()
